export const DEFAULT_PALETTE_ID: PaletteId = "inked";
export const DEFAULT_MATERIAL_ID: MaterialId = "minimal";

export function isPaletteId(value: string): value is PaletteId {
  return (PALETTE_IDS as readonly string[]).includes(value);
}

export function isMaterialId(value: string): value is MaterialId {
  return (MATERIAL_IDS as readonly string[]).includes(value);
}

/**
 * Resolve one palette + mode to runtime values. No derivation: every field
 * was emitted from the contract.
 *
 * `reduceTransparency` implements the mobile half of material-modes.md
 * §2.6 Fallback 2 — iOS Reduce Transparency / Android Remove animations are
 * reported by AccessibilityInfo, never by a CSS media query, so the swap
 * to the paired `-solid` roles has to happen here.
 */
export function resolveTheme(
  paletteId: PaletteId,
  materialId: MaterialId,
  reduceTransparency = false,
): Theme {
  const colors = PALETTE_COLORS[paletteId];
  const material = PALETTE_MATERIALS[paletteId][materialId];
  if (!colors || !material) {
    throw new Error(`UNKNOWN_THEME: ${paletteId}/${materialId} is not in tokens.json`);
  }
  const tier: PaletteTier = PALETTES.find((p) => p.id === paletteId)?.tier ?? "dark";
  if (!reduceTransparency) {
    return { paletteId, materialId, tier, colors, material };
  }
  return {
    paletteId,
    materialId,
    tier,
    colors,
    material: {
      ...material,
      surfaceOverlay: material.surfaceOverlaySolid,
      surfaceNav: material.surfaceNavSolid,
      surfaceSheet: material.surfaceSheetSolid,
      surfacePalette: material.surfacePaletteSolid,
      blurPx: 0,
      blurIntensity: 0,
      translucent: false,
      specular: "none",
      fresnel: "none",
    },
  };
}
